import numpy as np,pandas as pd,json
from fit_models import simulate,acceleration
from scipy.optimize import least_squares
D={s:pd.read_csv('data/'+s+'.csv') for s in ['train','val']}; F=json.load(open('results/fits.json'));out={}
for s,df in D.items():
 rows=[]
 for i,g in df.groupby('trajectory',sort=False):
  t,w,u,dw=g[['theta','omega','u','domega']].to_numpy().T;m=abs(w)>.5
  X=np.column_stack([u,-w,-np.sin(t),-np.sign(w)]);p=np.linalg.lstsq(X[m],dw[m],rcond=None)[0];r=X@p-dw
  row={'trajectory':int(i),'omega_vs_central_theta_rmse':float(np.sqrt(np.mean((np.gradient(t,.01)[1:-1]-w[1:-1])**2))),'base_regression':p.tolist(),'acceleration_rmse_moving':float(np.sqrt(np.mean(r[m]**2))),'terminal_u':float(u[-1]),'sign_acceleration_bias':[]}
  for mask in [m&(t<-.2),m&(t>.2),m&(w<-.5),m&(w>.5)]:row['sign_acceleration_bias'].append({'n':int(mask.sum()),'mean':float(r[mask].mean()) if mask.any() else None})
  rows.append(row); print(s,i,'theta-velocity',round(row['omega_vs_central_theta_rmse'],8),'basefit',np.round(p,3),'accnoise',round(row['acceleration_rmse_moving'],3),'neg/pos acc',row['sign_acceleration_bias'][:2])
 out[s+'_regressions']=rows
 # aggregate residuals grouped by regime, theta sign and velocity sign
 for kind in [0,1,4,5,9,12]:
  cats={}
  for i,g in df.groupby('trajectory',sort=False):
   a=g[['theta','omega','u','domega']].to_numpy();t,w,u,dw=a.T;p=np.array(F[str(kind)]['p']);r=simulate(a,p,kind)-t
   for cat,mask in [('rest',abs(w)<.05),('moving',abs(w)>.5),('negative_theta_moving',(t<-.2)&(abs(w)>.5)),('positive_theta_moving',(t>.2)&(abs(w)>.5)),('driven',np.full(len(t),bool(np.any(u)))),('free',np.full(len(t),not bool(np.any(u))))]:
    mask[0]=False;cats.setdefault(cat,[]).extend(r[mask])
  out[s+'_kind'+str(kind)]={c:{'n':len(v),'bias':float(np.mean(v)),'rmse':float(np.sqrt(np.mean(np.array(v)**2))),'sse':float(np.sum(np.array(v)**2))} for c,v in cats.items()}
 print('aggregate m0',out[s+'_kind0']);print('aggregate m1',out[s+'_kind1'])
 # moving-row exact duplicates, not stationary repeats
 a=df.loc[abs(df.omega)>.5,['theta','omega','u','domega']];out[s+'_moving_duplicates']=int(a.duplicated().sum())
print('moving duplicates',out['train_moving_duplicates'],out['val_moving_duplicates'])
a=D['train'];b=D['val'];keys=['theta','omega','u','domega'];same=a.loc[abs(a.omega)>.5].merge(b.loc[abs(b.omega)>.5],on=keys,suffixes=('_train','_val'))
print('train-val moving exact overlap',len(same));out['moving_overlap_trainval_n']=len(same)
json.dump(out,open('results/residual_diagnostics_more.json','w'),indent=2)

